const http = require('node:http');
const puerto = process.env.PORT ?? '3000';
const entorno = process.env.APP_ENV ?? 'dev';
const baseDeDatos = process.env.DATABASE_URL ?? 'postgres://localhost/despachos_dev';

http.createServer((req, res) => {
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify({ entorno, host_base: new URL(baseDeDatos).host }));
}).listen(puerto, '127.0.0.1', () => console.log(`escuchando en ${puerto} (${entorno})`));

const http = require('node:http');
const puerto = Number(process.env.PORT);
const limite = Number(process.env.LIMITE_KG);          // peso máximo por bulto
http.createServer((req, res) => {
  const kg = Number(new URL(req.url, 'http://x').searchParams.get('kg'));
  const base = new URL(process.env.DATABASE_URL);       // se usa recién al primer pedido
  res.end(kg > limite ? 'rechazado\n' : `ok, base ${base.host}\n`);
}).listen(puerto, '127.0.0.1', () => console.log('listo en', puerto));

import { z } from 'zod';

const Esquema = z.object({
  APP_ENV: z.enum(['dev', 'staging', 'prod']).default('dev'),
  PORT: z.coerce.number().int().min(1024).max(65535).default(3000),
  DATABASE_URL: z.url(),
  LIMITE_KG: z.coerce.number().positive().default(20),
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
  CLAVE_API: z.string().min(16),
});

const r = Esquema.safeParse(process.env);
if (!r.success) {
  console.error('Configuración inválida, no arranco:');
  for (const i of r.error.issues) console.error(`  - ${i.path.join('.')}: ${i.message}`);
  process.exit(78);
}
export const config = Object.freeze(r.data);

