import { readFileSync } from 'node:fs';

export function leerSecreto(nombre) {
  const ruta = process.env[`${nombre}_FILE`];
  if (ruta) return readFileSync(ruta, 'utf8').trim();
  const v = process.env[nombre];
  if (!v) throw new Error(`falta ${nombre} o ${nombre}_FILE`);
  return v;
}

import { createHash } from 'node:crypto';
import { readFileSync, statSync } from 'node:fs';

// Número estable de 0 a 99 para (flag, cliente): el mismo cliente cae siempre en el mismo lugar.
export function cubeta(flag, clienteId, sal = flag) {
  const h = createHash('sha256').update(`${sal}:${clienteId}`).digest();
  return h.readUInt32BE(0) % 100;
}

export function crearFlags(ruta) {
  let mtime = 0, tabla = {};
  function recargar() {
    const m = statSync(ruta).mtimeMs;
    if (m !== mtime) { tabla = JSON.parse(readFileSync(ruta, 'utf8')); mtime = m; }
  }
  return {
    activa(nombre, clienteId) {
      try { recargar(); } catch { /* si el archivo falla, queda la última tabla buena */ }
      const f = tabla[nombre];
      if (!f || f.activo !== true) return false;           // desconocida o apagada: apagada
      if (f.habilitados?.includes(clienteId)) return true;  // lista blanca
      return cubeta(nombre, clienteId) < (f.porcentaje ?? 100);
    },
  };
}
